import{_ as t,o as d,c as a,a4 as o}from"./chunks/framework.BaMAT_0D.js";const b=JSON.parse('{"title":"Lab2：CPU 调试测试环境","description":"","frontmatter":{},"headers":[],"relativePath":"Lab/Computer_Organization/IP2SOC/README.md","filePath":"Lab/Computer_Organization/IP2SOC/README.md","lastUpdated":1793361941000}'),c={name:"Lab/Computer_Organization/IP2SOC/README.md"};function s(i,e,r,n,l,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="lab2-cpu-调试测试环境" tabindex="-1">Lab2：CPU 调试测试环境 <a class="header-anchor" href="#lab2-cpu-调试测试环境" aria-label="Permalink to &quot;Lab2：CPU 调试测试环境&quot;">​</a></h1><p>按照提供的 <code>CSSTE.pdf</code>、实验要求及 PPT 71、85–93 页组织顶层模块。顶层为 <code>rtl/CSSTE.v</code>，目标器件沿用原 IP 的 <code>xc7a100tcsg324-1</code>，板级管脚沿用原 <code>A7.xdc</code>，并补充 100 MHz 输入时钟约束。原始资料保留在上一级 <code>provided</code> 目录。</p><p>本实验要求不需要实验报告；本文件用于构建和验收操作。</p><h2 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h2><p>双击 <code>build.cmd</code>，或在 Vivado Tcl Console 中执行（工程文件夹路径可按实际位置修改）：</p><div class="language-tcl vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">tcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {F:/Zhejiang University/Computer Organization/lab/lab2/OExp0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-IP2SOC/scripts/build.tcl}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>脚本自动建立 <code>build/lab2.xpr</code>，通过 IP Catalog 生成 <code>Seg7_Dev_0</code> 和 ROM <code>ROM_D</code>（Distributed Memory Generator，ROM、深度 1024、宽度 32，以 <code>mem/I_mem.coe</code> 初始化，异步 spo 输出），加入其他模块的 <code>.v</code> 接口及 <code>.edf</code> 网表，执行综合、实现和 bitstream 生成。成功后文件为 <code>output/CSSTE.bit</code>，并产生 DRC、资源和时序报告。再次构建将打开已有工程继续运行；脚本检测到源文件更新时会重置综合并重新实现。已有工程目录不会被脚本覆盖或删除。</p><p>只创建工程、不开始综合时运行 <code>scripts/create_project.tcl</code>。工程建立后可直接打开 <code>build/lab2.xpr</code>。更换电脑或目录时重新创建工程：先将旧 <code>build</code> 文件夹改名保留，再执行创建脚本；脚本会更新 VGA 的两个初始化文件绝对路径。其他 Vivado 安装位置可修改 <code>build.cmd</code> 中的 <code>LAB2_VIVADO</code>。</p><p>通过 GUI 手工添加时：将 <code>ip/Seg7_Dev</code> 加入 IP Repository 并生成名为 <code>Seg7_Dev_0</code> 的 IP；按上述参数创建 <code>ROM_D</code>；添加 <code>rtl/CSSTE.v</code>、<code>rtl/vga/*.v</code>、<code>ip/netlist</code> 中的全部 <code>.v</code> 和 <code>.edf</code>、<code>mem</code> 中两个 <code>.mem</code> 和 <code>constraints</code> 下两个 <code>.xdc</code>。不要把 <code>provided</code> 中的其他旧工程、VGA stub 或 VGA.edf 同时导入。</p><h2 id="模块与连线" tabindex="-1">模块与连线 <a class="header-anchor" href="#模块与连线" aria-label="Permalink to &quot;模块与连线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>实例</th><th>模块</th><th>功能</th></tr></thead><tbody><tr><td>U1</td><td>SCPU</td><td>课程给出的 CPU 网表，Lab4 在此替换</td></tr><tr><td>U2</td><td>ROM_D</td><td><code>PC_out[11:2]</code> 访问 32 位指令</td></tr><tr><td>U3</td><td>RAM_B</td><td>数据 RAM，时钟为 <code>~clk_100mhz</code></td></tr><tr><td>U4</td><td>MIO_BUS</td><td>CPU、RAM、外设数据通路</td></tr><tr><td>U5</td><td>Multi_8CH32</td><td>8 路数码管显示数据选择</td></tr><tr><td>U6</td><td>Seg7_Dev_0</td><td><code>clkdiv[18:16]</code> 扫描数码管</td></tr><tr><td>U7</td><td>SPIO</td><td>LED 与计数器通道控制</td></tr><tr><td>U8</td><td>clk_div</td><td>分频与 CPU 时钟模式</td></tr><tr><td>U9</td><td>SAnti_jitter</td><td>按键、开关去抖和低有效 RSTN 转换</td></tr><tr><td>U10</td><td>Counter_x</td><td>三路定时计数器</td></tr><tr><td>U11</td><td>VGA</td><td>25 MHz 像素时钟，显示 CPU 调试信号</td></tr></tbody></table><p>U4、U5、U7、U10 使用 <code>~Clk_CPU</code>；手动 STEP 使用去抖后的 <code>SW_OK[10]</code>。<code>MIO_ready</code> 接 0；未使用的输出端口明确留空。VGA 内部未提供的寄存器、控制信号输入明确接 0，以符合实验要求中的全零显示。VGA 使用原有扫描与字符显示结构，并修正了源文件中将 ASCII 编码减去行号的错误（这会把第 2 行的数字 0 显示成点号）。RAM 返回数据在 VGA 内增加一级 100 MHz 寄存，将 RAM/总线与字符选择逻辑分开，观测延迟增加 10ns；CPU 和 RAM 的功能与连线不变。</p><h2 id="上板验收" tabindex="-1">上板验收 <a class="header-anchor" href="#上板验收" aria-label="Permalink to &quot;上板验收&quot;">​</a></h2><ol><li>在 Hardware Manager 连接开发板并下载 <code>output/CSSTE.bit</code>，连接 VGA 显示器。</li><li>设置 <code>SW[8]=1, SW[2]=0, SW[10]=0</code>，按板上 C12 的 RESET 复位，再松开。</li><li><code>SW[7:5]=111</code> 时数码管显示字节 PC；复位后应为 <code>00000000</code>。<code>010</code> 显示首条指令 <code>00100093</code>；<code>100</code> 显示首条指令的 ALU 结果 <code>00000001</code>。</li><li>将 <code>SW[10]</code> 从 0 拨到 1，应执行一次指令；拨回 0 再拨 1，继续执行。等待去抖稳定，PC 从 0 到 4、8、C……，到 <code>0000007C</code> 的分支指令后回到 0。</li><li><code>SW[8]=0, SW[2]=1</code> 为自动慢速单步，观察 PC、指令和 ALU 连续变化；<code>00</code> 为全速运行，适合慢速观察后再尝试。</li><li>VGA 显示字节 PC（正常顺序每次加 4）、当前指令及当前组合 ALU 结果；未接入的寄存器等区域显示 0。改变数码管显示选择不应改变 VGA 的这些信息。</li></ol><table tabindex="0"><thead><tr><th>SW[7:5]</th><th>数码管内容</th></tr></thead><tbody><tr><td>000</td><td>总线外设显示数据（由程序写入锁存；本 demo 无此写入）</td></tr><tr><td>001</td><td>指令字地址 <code>{2&#39;b0,PC_out[31:2]}</code>，顺序每次加 1</td></tr><tr><td>010</td><td>指令 <code>Inst_in</code></td></tr><tr><td>011</td><td>计数器 <code>counter_out</code></td></tr><tr><td>100</td><td>ALU 地址结果 <code>Addr_out</code></td></tr><tr><td>101</td><td>CPU 写数据 <code>Data_out</code></td></tr><tr><td>110</td><td>CPU 读数据 <code>Data_in</code></td></tr><tr><td>111</td><td>指令字节地址 <code>PC_out</code>，顺序每次加 4</td></tr></tbody></table><p>VGA/数码管展示的是<strong>当前 PC 对应指令的组合输出</strong>，上升沿之后 PC 移到下一条指令；不要将它误认为上一条指令的写回值。分支周期的 ALU 结果由给定 CPU 实现决定，参考表对此留空。</p><h2 id="验证与参考结果" tabindex="-1">验证与参考结果 <a class="header-anchor" href="#验证与参考结果" aria-label="Permalink to &quot;验证与参考结果&quot;">​</a></h2><p>在本目录执行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">check_demo.py</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python tests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">check_sources.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>前者解码原 COE 的全部 32 条指令，执行两轮，按独立 Fibonacci 递推校验，并生成 <code>output/demo_reference.csv</code>。后者核对 11 个顶层实例的命名端口、8 组 EDF 依赖、Seg7 封装文件及全部 68 个唯一板级引脚。两者不等同于给定 SCPU 网表功能仿真，也不代替板卡实测。</p><p>原资料从 PC <code>0x3C</code> 开始有数值错误。正确的部分结果为：<code>0x3C → 000003DB</code>、<code>0x40 → 0000063D</code>、<code>0x44 → 00000A18</code>、<code>0x78 → 00148ADD</code>，完整结果见 CSV。<code>0x3C</code> 的值本身正确，后续请以独立计算结果为准。</p><p>VGA 字符显示另有真实 HDL 回归测试 <code>tests/tb_vga.sv</code>。在已配置 Vivado 命令环境的本目录中执行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xvlog --sv rtl/vga/VgaDisplay.v tests/tb_vga.sv</span></span>
<span class="line"><span>xelab tb_vga -s vga_check</span></span>
<span class="line"><span>xsim vga_check -R</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>应看到 <code>PASS: VGA static label, PC zero digit, dynamic character write across rows</code>。相同测试在修正前的提供源码上于 1ns 失败，输出 <code>PC digit must be ASCII 0, got 2e</code>；修正后在 7ns 通过。此测试验证实际字符寻址和写入，不是整机 CPU 仿真。</p><h2 id="本次构建结果" tabindex="-1">本次构建结果 <a class="header-anchor" href="#本次构建结果" aria-label="Permalink to &quot;本次构建结果&quot;">​</a></h2><p>Vivado 2025.2 已完成综合、布局布线和 bitstream 生成，DRC 为 0 个 Error。已约束路径 WNS 为 +0.534 ns，TNS 为 0.000 ns。分频/手动时钟及外部 IO 仍有未约束路径，不能把该结果解读为所有模式已完成时序签核。尚未上板实测；详细边界与证据见 <code>output/VERIFICATION.md</code>、<code>output/timing_summary.rpt</code> 和 <code>output/drc.rpt</code>。</p>`,26)])])}const u=t(c,[["render",s]]);export{b as __pageData,u as default};
